        _edit('rad_core_h-0', '    /* --gpu-memory-mib: claim this much of every card; 0 uses gpu_headroom_mib. Inverse of\n     * headroom: N + headroom = the card, in MiB. Not with --gpu-headroom-mib. */\n    int64_t gpu_memory_mib = 0;\n    /* --kv-cache-dtype bf16|fp8|fp8_v4|k6_v4|bf16_fp8. fp8 is an E4M3 cache with per-(sequence,\n     * head) descales; it halves the per-token cost, most of the KV pool at production context. fp8_v4\n     * keeps K as E4M3 and V as int4 in groups of 32, k6_v4 also K as int6, bf16_fp8 keeps K as bf16\n     * and V as E4M3 (RadBuildCtx::kv_quant), served only where the plugin says so. Each changes the model\'s output slightly, so it is\n     * explicit and bf16 is the default. No "auto": it would always resolve to bf16 and only add\n     * another name. */\n    std::string kv_cache_dtype = "bf16";\n', '    /* --gpu-memory-mib: claim this much of every card; 0 uses gpu_headroom_mib. Inverse of\n     * headroom: N + headroom = the card, in MiB. Not with --gpu-headroom-mib. */\n    int64_t gpu_memory_mib = 0;\n    /* --kv-cache-dtype bf16|fp8|fp8_v4|k6_v4|bf16_fp8|bf16_i8. fp8 is an E4M3 cache with per-(sequence,\n     * head) descales; it halves the per-token cost, most of the KV pool at production context. fp8_v4\n     * keeps K as E4M3 and V as int4 in groups of 32, k6_v4 also K as int6, bf16_fp8 keeps K as bf16\n     * and V as E4M3, bf16_i8 K as bf16 and V as int8 in groups of 32 with an f16 scale\n     * (RadBuildCtx::kv_quant), served only where the plugin says so. Each changes the model\'s output slightly, so it is\n     * explicit and bf16 is the default. No "auto": it would always resolve to bf16 and only add\n     * another name. */\n    std::string kv_cache_dtype = "bf16";\n', '/* --kv-cache-dtype bf16|fp8|fp8_v4|k6_v4|bf16_fp8|bf16_i8. fp8 is an E4M3 cache with per-(sequence,'),
