        _edit('r4d_selftest_cpp-0', '\n#include "rad_abi.h"\n#include "rad_plugin.h"\n#include "r4d_args.h"\n#include "r4d_ar_shards.h"\n#include "r4d_ar_links.h"\n', '\n#include "rad_abi.h"\n#include "rad_plugin.h"\n#include "rad_builder.h"   /* RAD_KVQ_B16I8_GROUP, RAD_KVQ_B16I8_ROW16 */\n#include "r4d_args.h"\n#include "r4d_ar_shards.h"\n#include "r4d_ar_links.h"\n', '#include "rad_builder.h"   /* RAD_KVQ_B16I8_GROUP, RAD_KVQ_B16I8_ROW16 */'),
        _edit('r4d_selftest_cpp-1', "     * it. kvq 2, k6_v4: K's low nibbles, its high-bit words, V's codes, K's scales, V's scales\n     * (RAD_KVQ_K6V4 in abi/rad_builder.h); K is (code ^ 32) - 32 times its scale. */\n    /* kvq 3, bf16_fp8: head_dim bf16 K elements, then head_dim E4M3 V bytes (RAD_KVQ_B16F8). */\n    const int v4 = kvq == 1 || kvq == 2;\n    const int64_t so = kvq == 3 ? 3 * head_dim : kvq == 2 ? 22 * head_dim / 16 : v4 ? 25 * head_dim / 16 : 2 * head_dim;\n    const int64_t voff = kvq == 2 ? head_dim * 3 / 4 : head_dim;\n    const int64_t vsoff = kvq == 2 ? head_dim * 21 / 16 : head_dim * 3 / 2;\n    const auto f16at = [](const uint8_t* p) {\n", "     * it. kvq 2, k6_v4: K's low nibbles, its high-bit words, V's codes, K's scales, V's scales\n     * (RAD_KVQ_K6V4 in abi/rad_builder.h); K is (code ^ 32) - 32 times its scale. */\n    /* kvq 3, bf16_fp8: head_dim bf16 K elements, then head_dim E4M3 V bytes (RAD_KVQ_B16F8). */\n    /* kvq 4, bf16_i8: head_dim bf16 K elements, head_dim int8 V codes, then an f16 scale per\n     * RAD_KVQ_B16I8_GROUP dims; V is the code times its group's scale (RAD_KVQ_B16I8). */\n    const int v4 = kvq == 1 || kvq == 2;\n    const int64_t so = kvq == 4 ? RAD_KVQ_B16I8_ROW16 * head_dim / 16\n                     : kvq == 3 ? 3 * head_dim : kvq == 2 ? 22 * head_dim / 16 : v4 ? 25 * head_dim / 16 : 2 * head_dim;\n    const int64_t voff = kvq == 2 ? head_dim * 3 / 4 : head_dim;\n    const int64_t vsoff = kvq == 2 ? head_dim * 21 / 16 : head_dim * 3 / 2;\n    const auto f16at = [](const uint8_t* p) {\n", '/* kvq 4, bf16_i8: head_dim bf16 K elements, head_dim int8 V codes, then an f16 scale per'),
        _edit('r4d_selftest_cpp-2', '            const int hi = (row[head_dim / 2 + (d / 16) * 4 + (x & 7) / 2] >> ((x & 1) * 2 + (x >> 3) * 4)) & 3;\n            return (float)(((lo | (hi << 4)) ^ 32) - 32) * f16at(row + head_dim * 5 / 4 + (d / 32) * 2);\n        }\n        if (kvq == 3) {\n            uint16_t b; std::memcpy(&b, kv + blk * sb + kh * sh + slot * so + 2 * d, 2);\n            return h_bf16(b);\n        }\n', '            const int hi = (row[head_dim / 2 + (d / 16) * 4 + (x & 7) / 2] >> ((x & 1) * 2 + (x >> 3) * 4)) & 3;\n            return (float)(((lo | (hi << 4)) ^ 32) - 32) * f16at(row + head_dim * 5 / 4 + (d / 32) * 2);\n        }\n        if (kvq == 3 || kvq == 4) {\n            uint16_t b; std::memcpy(&b, kv + blk * sb + kh * sh + slot * so + 2 * d, 2);\n            return h_bf16(b);\n        }\n', 'if (kvq == 3 || kvq == 4) {'),
        _edit('r4d_selftest_cpp-3', '            return (float)((nib ^ 8) - 8) * f16at(row + vsoff + (d / 32) * 2);\n        }\n        if (kvq == 3) return h_e4m3(kv[blk * sb + kh * sh + slot * so + 2 * head_dim + d]);\n        const uint8_t* p = kv + (blk * sb + kh * sh + slot * so + head_dim + d) * ew;\n        return kv_is_fp8 ? h_e4m3(p[0]) : h_bf16(*(const uint16_t*)p);\n    };\n', '            return (float)((nib ^ 8) - 8) * f16at(row + vsoff + (d / 32) * 2);\n        }\n        if (kvq == 3) return h_e4m3(kv[blk * sb + kh * sh + slot * so + 2 * head_dim + d]);\n        if (kvq == 4) {\n            const uint8_t* row = kv + blk * sb + kh * sh + slot * so;\n            return (float)(int8_t)row[2 * head_dim + d] *\n                   f16at(row + 3 * head_dim + (d / RAD_KVQ_B16I8_GROUP) * 2);\n        }\n        const uint8_t* p = kv + (blk * sb + kh * sh + slot * so + head_dim + d) * ew;\n        return kv_is_fp8 ? h_e4m3(p[0]) : h_bf16(*(const uint16_t*)p);\n    };\n', 'return (float)(int8_t)row[2 * head_dim + d] *'),
        _edit('r4d_selftest_cpp-4', "}\n\n/* A token's bytes in a (block, head) page of an 8-bit cache: kvq 0 fp8 (K then V), 1 fp8_v4, 2\n * k6_v4 (attn_oracle_one has the layouts). */\nstatic int64_t kvq_row_bytes(int64_t head_dim, int kvq) {\n    return kvq == 3 ? 3 * head_dim : kvq == 2 ? 22 * head_dim / 16 : kvq == 1 ? 25 * head_dim / 16 : 2 * head_dim;\n}\n\n/* Over random E4M3 bytes in every row of an fp8_v4 (kvq 1) or k6_v4 (kvq 2) cache: V's int4 codes\n", '}\n\n/* A token\'s bytes in a (block, head) page of an 8-bit cache: kvq 0 fp8 (K then V), 1 fp8_v4, 2\n * k6_v4, 3 bf16_fp8, 4 bf16_i8 (attn_oracle_one has the layouts). */\nstatic int64_t kvq_row_bytes(int64_t head_dim, int kvq) {\n    return kvq == 4 ? RAD_KVQ_B16I8_ROW16 * head_dim / 16\n         : kvq == 3 ? 3 * head_dim : kvq == 2 ? 22 * head_dim / 16 : kvq == 1 ? 25 * head_dim / 16 : 2 * head_dim;\n}\n/* The kvq of an attn_paged row\'s kv_dtype (0 for the plain fp8 and bf16 caches). */\nstatic int kvq_of(const char* kv_dtype) {\n    return !std::strcmp(kv_dtype, "fp8_v4") ? 1 : !std::strcmp(kv_dtype, "k6_v4") ? 2\n         : !std::strcmp(kv_dtype, "bf16_fp8") ? 3 : !std::strcmp(kv_dtype, "bf16_i8") ? 4 : 0;\n}\n\n/* Over random E4M3 bytes in every row of an fp8_v4 (kvq 1) or k6_v4 (kvq 2) cache: V\'s int4 codes\n', '* k6_v4, 3 bf16_fp8, 4 bf16_i8 (attn_oracle_one has the layouts). */'),
        _edit('r4d_selftest_cpp-5', " * +-2. fp8_v4's K stays the E4M3 bytes. */\nstatic void kvq_fill_rows(std::vector<uint8_t>& kv, int64_t nelem, int64_t rowe, int64_t head_dim,\n                          int kvq) {\n    if (kvq == 3) {\n        /* bf16_fp8: K as bf16 in [-1, 1] over the E4M3 bytes already there (V, bounded the same),\n         * with the layout's edge values planted in V: the saturation bound, a subnormal, zeros of\n", " * +-2. fp8_v4's K stays the E4M3 bytes. */\nstatic void kvq_fill_rows(std::vector<uint8_t>& kv, int64_t nelem, int64_t rowe, int64_t head_dim,\n                          int kvq) {\n    if (kvq == 4) {\n        /* bf16_i8: K as bf16 in [-1, 1]; V's int8 codes over the whole -127..127 and a scale of\n         * 1/256 to 1/64 a group, so V spans about +-2. Every seventh row carries the layout's edge\n         * groups: a zero scale over codes that are not zero (must decode to zero: the dequant\n         * multiplies, it never divides), a zero group as the store writes it (scale 0, codes 0), the\n         * smallest scale the store writes (2^-14, the smallest normal f16) under full-range codes,\n         * and the extreme codes 127 and -127 beside 1, -1, 0 and -128 (a byte the store never\n         * writes, read as two's complement). */\n        const int64_t G = RAD_KVQ_B16I8_GROUP, ng = head_dim / G;\n        for (int64_t r0 = 0; r0 < nelem; r0 += rowe) {\n            uint8_t* row = &kv[(size_t)r0];\n            uint8_t* vc = row + 2 * head_dim;\n            uint8_t* vs = row + 3 * head_dim;\n            for (int64_t d = 0; d < head_dim; ++d) {\n                const uint16_t b = st_rand_bf16((uint32_t)(r0 / rowe * 131 + d));\n                std::memcpy(row + 2 * d, &b, 2);\n                const uint8_t c = (uint8_t)(st_rand_e4m3((uint32_t)(r0 * 7 + d)) * 37u + (uint32_t)d);\n                vc[d] = c == 0x80u ? 0x81u : c;\n            }\n            for (int64_t g = 0; g < ng; ++g) {\n                const _Float16 sc = (_Float16)(0.00390625f * (float)(1 + (st_rand_e4m3((uint32_t)(r0 + g)) & 3)));\n                std::memcpy(vs + g * 2, &sc, 2);\n            }\n            if ((r0 / rowe) % 7 == 3) {\n                const uint16_t zero = 0, tiny = 0x0400;\n                std::memcpy(vs + 0 * 2, &zero, 2);                       /* group 0: scale 0, live codes */\n                std::memcpy(vs + 1 * 2, &zero, 2);                       /* group 1: a stored zero group */\n                std::memset(vc + 1 * G, 0, (size_t)G);\n                std::memcpy(vs + 2 * 2, &tiny, 2);                       /* group 2: scale 2^-14 */\n                vc[2 * G] = 0x7F; vc[2 * G + 1] = 0x81;\n                static const uint8_t edge[] = { 0x7F, 0x81, 0x01, 0xFF, 0x00, 0x80 };\n                for (int64_t d = 0; d < 6; ++d) vc[3 * G + d] = edge[d];   /* group 3: the extremes */\n            }\n        }\n        return;\n    }\n    if (kvq == 3) {\n        /* bf16_fp8: K as bf16 in [-1, 1] over the E4M3 bytes already there (V, bounded the same),\n         * with the layout's edge values planted in V: the saturation bound, a subnormal, zeros of\n", "/* bf16_i8: K as bf16 in [-1, 1]; V's int8 codes over the whole -127..127 and a scale of"),
        _edit('r4d_selftest_cpp-6', '    const int64_t max_blocks = (ctx + bs - 1) / bs;   /* a ctx past a whole block: a partial last one */\n    const int64_t total_q = seqs * q_len;\n    const int kv_is_fp8 = std::strcmp(kv_dtype, "bf16") != 0;\n    const int kvq = !std::strcmp(kv_dtype, "fp8_v4") ? 1 : !std::strcmp(kv_dtype, "k6_v4") ? 2\n                  : !std::strcmp(kv_dtype, "bf16_fp8") ? 3 : 0;\n    const int v4 = kvq != 0;\n    const uint32_t kvdt = kv_is_fp8 ? RAD_F8E4M3 : RAD_BF16;\n    const int ew = kv_is_fp8 ? 1 : 2;\n', '    const int64_t max_blocks = (ctx + bs - 1) / bs;   /* a ctx past a whole block: a partial last one */\n    const int64_t total_q = seqs * q_len;\n    const int kv_is_fp8 = std::strcmp(kv_dtype, "bf16") != 0;\n    const int kvq = kvq_of(kv_dtype);\n    const int v4 = kvq != 0;\n    const uint32_t kvdt = kv_is_fp8 ? RAD_F8E4M3 : RAD_BF16;\n    const int ew = kv_is_fp8 ? 1 : 2;\n', '    const int kvq = kvq_of(kv_dtype);\n    const int v4 = kvq != 0;'),
        _edit('r4d_selftest_cpp-7', '    const int64_t q_heads = kv_heads * gqa, bq = 384 / gqa;\n    const int64_t ns = (int64_t)seqs.size();\n    const int kv_is_fp8 = std::strcmp(kv_dtype, "bf16") != 0;\n    const int kvq = !std::strcmp(kv_dtype, "fp8_v4") ? 1 : !std::strcmp(kv_dtype, "k6_v4") ? 2\n                  : !std::strcmp(kv_dtype, "bf16_fp8") ? 3 : 0;\n    const int v4 = kvq == 1 || kvq == 2;\n    const uint32_t kvdt = kv_is_fp8 ? RAD_F8E4M3 : RAD_BF16;\n    const int ew = kv_is_fp8 ? 1 : 2;\n', '    const int64_t q_heads = kv_heads * gqa, bq = 384 / gqa;\n    const int64_t ns = (int64_t)seqs.size();\n    const int kv_is_fp8 = std::strcmp(kv_dtype, "bf16") != 0;\n    const int kvq = kvq_of(kv_dtype);\n    const int v4 = kvq == 1 || kvq == 2;\n    const uint32_t kvdt = kv_is_fp8 ? RAD_F8E4M3 : RAD_BF16;\n    const int ew = kv_is_fp8 ? 1 : 2;\n', '    const int kvq = kvq_of(kv_dtype);\n    const int v4 = kvq == 1 || kvq == 2;'),
        _edit('r4d_selftest_cpp-8', '        if (kv_is_fp8) kv[bo] = st_rand_e4m3(e);\n        else { const uint16_t h = st_rand_bf16(e); kv[bo] = (uint8_t)h; kv[bo + 1] = (uint8_t)(h >> 8); }\n    }\n    if (kvq == 3) kvq_fill_rows(kv, nelem, rowe, head_dim, kvq);\n    else if (v4)\n        for (int64_t r0 = 0; r0 < nelem; r0 += rowe) {\n            uint8_t* row = &kv[(size_t)r0];\n', '        if (kv_is_fp8) kv[bo] = st_rand_e4m3(e);\n        else { const uint16_t h = st_rand_bf16(e); kv[bo] = (uint8_t)h; kv[bo + 1] = (uint8_t)(h >> 8); }\n    }\n    if (kvq >= 3) kvq_fill_rows(kv, nelem, rowe, head_dim, kvq);\n    else if (v4)\n        for (int64_t r0 = 0; r0 < nelem; r0 += rowe) {\n            uint8_t* row = &kv[(size_t)r0];\n', '    }\n    if (kvq >= 3) kvq_fill_rows(kv, nelem, rowe, head_dim, kvq);'),
