        _edit('r4d_selftest_cpp-14', '       bad ? first : fmt("every live row decodes exactly; %d bytes of other rows touched", touched));\n}\n\nstatic void kv_store_case(const Plugin& pl, const char* name, const char* kv_dtype,\n                          bool latent = false) {\n    if (!sel(name)) return;\n', '       bad ? first : fmt("every live row decodes exactly; %d bytes of other rows touched", touched));\n}\n\n/* The bf16_i8 quantiser from the layout\'s definition (RAD_KVQ_B16I8, abi/rad_builder.h), in host\n * arithmetic that shares nothing with the kernels\': a group\'s scale is the smallest f16 s with\n * 127 * s >= absmax, held to [2^-14, 515.5], 0 for a group of zeros; a code is\n * clamp(rint(v / s), -127, 127), 0 under a zero scale. NaN elements are ignored by the absmax and\n * take the lower clamp. */\nstatic uint16_t h_i8_scale_bits(float amax) {\n    if (!(amax > 0.0f)) return 0;\n    const auto val = [](uint16_t b) { return (double)__builtin_bit_cast(_Float16, b); };\n    /* Positive finite f16 order as their bits: the first from 2^-14 (0x0400) whose 127-fold reaches\n     * the absmax, or 515.5 (0x6007) when none up to it does (the group then clips). */\n    uint16_t lo = 0x0400, hi = 0x6007;\n    while (lo < hi) {\n        const uint16_t mid = (uint16_t)((lo + hi) / 2);\n        if (val(mid) * 127.0 >= (double)amax) hi = mid; else lo = (uint16_t)(mid + 1);\n    }\n    return lo;\n}\nstatic int8_t h_i8_code(float v, float sc) {\n    if (!(sc > 0.0f)) return 0;\n    const float r = std::nearbyint(v / sc);\n    return (int8_t)std::fmin(std::fmax(r, -127.0f), 127.0f);\n}\n\n/* kv_store into the bf16_i8 cache: K stored bit-exact as bf16 (kv_store_b16f8_case\'s set), V as\n * int8 with an f16 scale per group. Every live row\'s scales and codes are compared byte for byte\n * with the host quantiser above, over groups built to reach each rule of the layout: a group of\n * zeros of both signs (scale 0, codes 0); integers -127..127 times a power of two with both\n * extremes present (the scale is the step and every code decodes back to its input exactly);\n * random values (round-to-nearest of absmax / 127 goes below it in about half of them, where the\n * stored scale must be the next f16 up); an absmax of 1e-4 (the scale floor 2^-14) and one below\n * 2^-15 (the floor again, every code 0); values past 127 * 515.5 and infinities (the scale cap,\n * codes clamped to +-127) with a NaN (ignored by the absmax, a finite code); and one large value\n * among small ones. Beside the byte comparison, no finite value of a group under the cap may\n * decode further than half a scale from its input (a scale rounded down would clip the absmax).\n * A pad slot and one past the cache leave the sentinel row untouched. */\nstatic void kv_store_b16i8_case(const Plugin& pl) {\n    const char* name = "kv_store_b16i8";\n    if (!sel(name)) return;\n    const RadKernelInfo* r = find(pl, name);\n    if (!r) { ok(name, false, "row absent"); return; }\n    const int64_t head_dim = 256, kv_heads = 2, block_size = 16, n_blocks = 4;\n    const int64_t G = RAD_KVQ_B16I8_GROUP, ng = head_dim / G;\n    const int64_t lane = kv_heads * head_dim, rowb = RAD_KVQ_B16I8_ROW16 * head_dim / 16;\n    const std::vector<int32_t> slots = { 0, 17, 63, -1, (int32_t)(n_blocks * block_size), 33, 5, 46 };\n    const int64_t T_tok = (int64_t)slots.size();\n    static const uint16_t kbits[8] = { 0x3f80, 0xbf80, 0x7f7f, 0x0001, 0x8000, 0x4049, 0xc2f7, 0x0080 };\n    auto kb = [&](int64_t t, int64_t h, int64_t d) { return kbits[(size_t)((t + h * 3 + d) % 8)]; };\n    /* a group\'s kind, so every kind meets every token and head and every group index */\n    auto kind = [&](int64_t t, int64_t h, int64_t g) { return (int)((g + t + 3 * h) % 8); };\n    auto vbits = [&](int64_t t, int64_t h, int64_t d) -> uint16_t {\n        const int64_t g = d / G, x = d % G;\n        const uint32_t rr = st_mix32((uint32_t)(t * 100003 + h * 7919 + d * 31 + 17));\n        const float u = ((rr & 0x00ffffffu) / 16777215.0f) * 2.0f - 1.0f;     /* [-1, 1] */\n        switch (kind(t, h, g)) {\n        case 0: return (x & 1) ? 0x8000 : 0x0000;                              /* +-0 */\n        case 1: {                                                              /* the exact grid */\n            const int q = x == 3 ? -127 : x == (G > 26 ? 26 : G - 1) ? 127 : (int)(rr % 255u) - 127;\n            return h_to_bf16((float)q * std::ldexp(1.0f, (int)((t + h) % 4) - 3));\n        }\n        case 2: return h_to_bf16(u * 3.0f);                                    /* random */\n        case 3: return h_to_bf16(x == 1 ? 1.0e-4f : x == 2 ? -1.0e-4f : u * 1.0e-4f);   /* the floor */\n        case 4: return h_to_bf16(u * 1.0e-5f);                                 /* below half the floor */\n        case 5: {                                                              /* the cap */\n            static const uint16_t big[8] = { 0x7149 /* 1e30 */, 0xf149, 0x4789 /* 70144 */, 0x477e /* 65024 */,\n                                             0x4396 /* 300 */, 0x7f80 /* inf */, 0xff80, 0x7fc0 /* NaN */ };\n            return big[(size_t)(x % 8)];\n        }\n        case 6: return h_to_bf16(x == 5 ? 5.0f : u * 0.01f);                   /* one large value */\n        default: return h_to_bf16(u * (float)(1 + (int)(rr >> 28)) * 40.0f);    /* random, large */\n        }\n    };\n    std::vector<uint16_t> hk((size_t)T_tok * lane), hv((size_t)T_tok * lane);\n    for (int64_t t = 0; t < T_tok; ++t)\n        for (int64_t h = 0; h < kv_heads; ++h)\n            for (int64_t d = 0; d < head_dim; ++d) {\n                hk[(size_t)(t * lane + h * head_dim + d)] = kb(t, h, d);\n                hv[(size_t)(t * lane + h * head_dim + d)] = vbits(t, h, d);\n            }\n    const size_t cbytes = (size_t)(n_blocks * kv_heads * block_size * rowb);\n    void* d_k = dalloc((size_t)T_tok * lane * 2);\n    void* d_v = dalloc((size_t)T_tok * lane * 2);\n    void* d_sm = dalloc((size_t)T_tok * 4);\n    void* d_c = dalloc(cbytes);\n    if (!d_k || !d_v || !d_sm || !d_c) { ok(name, false, "hipMalloc failed"); return; }\n    st_memcpy(d_k, hk.data(), (size_t)T_tok * lane * 2, hipMemcpyHostToDevice);\n    st_memcpy(d_v, hv.data(), (size_t)T_tok * lane * 2, hipMemcpyHostToDevice);\n    st_memcpy(d_sm, slots.data(), (size_t)T_tok * 4, hipMemcpyHostToDevice);\n    st_memset(d_c, 0x7f, cbytes);\n    std::vector<RadTensor> ts = {\n        T(d_k,  RAD_BF16,   { T_tok, lane }),\n        T(d_v,  RAD_BF16,   { T_tok, lane }),\n        T(d_sm, RAD_I32,    { T_tok }),\n        T(d_c,  RAD_F8E4M3, { n_blocks, kv_heads, block_size, rowb }),\n    };\n    std::vector<RadParam> ps = {\n        PI("M", T_tok), PI("head_dim", head_dim), PI("n_head_kv", kv_heads),\n        PI("block_size", block_size), PS("kv_dtype", "bf16_i8"),\n    };\n    run_case(r, ts, ps);\n    std::vector<uint8_t> got(cbytes);\n    st_memcpy(got.data(), d_c, cbytes, hipMemcpyDeviceToHost);\n    int bad = 0, groups = 0, rounded_up = 0, floored = 0, capped = 0, zero = 0, codes = 0;\n    std::string first;\n    std::vector<bool> live_row((size_t)(n_blocks * block_size), false);\n    for (int64_t t = 0; t < T_tok; ++t) {\n        const int32_t s = slots[(size_t)t];\n        if (s < 0 || s / block_size >= n_blocks) continue;\n        live_row[(size_t)s] = true;\n        for (int64_t h = 0; h < kv_heads; ++h) {\n            const uint8_t* row = &got[(size_t)(((s / block_size) * kv_heads + h) * block_size\n                                               + s % block_size) * rowb];\n            for (int64_t d = 0; d < head_dim; ++d) {\n                uint16_t k;\n                std::memcpy(&k, row + 2 * d, 2);\n                if (k != kb(t, h, d)) {\n                    if (!bad) first = fmt("t%lld h%lld d%lld: k %04x (want %04x)", (long long)t,\n                                          (long long)h, (long long)d, k, kb(t, h, d));\n                    ++bad;\n                }\n            }\n            for (int64_t g = 0; g < ng; ++g) {\n                float amax = 0.0f;\n                for (int64_t x = 0; x < G; ++x)\n                    amax = std::fmax(amax, std::fabs(h_bf16(vbits(t, h, g * G + x))));\n                const uint16_t want_s = h_i8_scale_bits(amax);\n                uint16_t got_s;\n                std::memcpy(&got_s, row + 3 * head_dim + g * 2, 2);\n                const float sc = (float)__builtin_bit_cast(_Float16, want_s);\n                ++groups;\n                zero += want_s == 0;\n                floored += want_s == 0x0400;\n                capped += want_s == 0x6007 && (double)sc * 127.0 < (double)amax;\n                if (want_s > 0x0400 && want_s < 0x6007 &&\n                    (float)(_Float16)(amax / 127.0f) * 127.0f < amax) ++rounded_up;\n                if (got_s != want_s) {\n                    if (!bad) first = fmt("t%lld h%lld group %lld (kind %d): scale %04x (want %04x), absmax %g",\n                                          (long long)t, (long long)h, (long long)g, kind(t, h, g),\n                                          got_s, want_s, (double)amax);\n                    ++bad;\n                }\n                for (int64_t x = 0; x < G; ++x) {\n                    const int64_t d = g * G + x;\n                    const float v = h_bf16(vbits(t, h, d));\n                    const int8_t want_c = h_i8_code(v, sc);\n                    const int8_t got_c = (int8_t)row[2 * head_dim + d];\n                    ++codes;\n                    /* the stored scale\'s guarantee, from the stored bytes alone */\n                    const double dec = (double)got_c * (double)__builtin_bit_cast(_Float16, got_s);\n                    const bool clip = std::isfinite(v) && !(want_s == 0x6007 && (double)sc * 127.0 < (double)amax) &&\n                                      want_s != 0 && std::fabs(dec - (double)v) > 0.5000001 * (double)sc;\n                    const bool grid = kind(t, h, g) == 1 && dec != (double)v;\n                    if (got_c != want_c || clip || grid) {\n                        if (!bad) first = fmt("t%lld h%lld d%lld (kind %d): code %d (want %d) of v %g at "\n                                              "scale %04x%s%s", (long long)t, (long long)h, (long long)d,\n                                              kind(t, h, g), (int)got_c, (int)want_c, (double)v, got_s,\n                                              clip ? ", further than half a scale" : "",\n                                              grid ? ", the grid value does not decode back" : "");\n                        ++bad;\n                    }\n                }\n            }\n        }\n    }\n    int touched = 0;\n    for (int64_t s = 0; s < n_blocks * block_size; ++s) {\n        if (live_row[(size_t)s]) continue;\n        for (int64_t h = 0; h < kv_heads; ++h) {\n            const uint8_t* row = &got[(size_t)(((s / block_size) * kv_heads + h) * block_size\n                                               + s % block_size) * rowb];\n            for (int64_t b = 0; b < rowb; ++b) touched += row[b] != 0x7f;\n        }\n    }\n    /* the set reached every rule it was built for, or the comparison above proved less than it says */\n    const bool reached = zero > 0 && floored > 0 && capped > 0 && rounded_up > 0;\n    ok(fmt("%s: %d codes and %d scales against the host quantiser (%d zero groups, %d at the floor, %d "\n           "at the cap, %d rounded up past round-to-nearest)", name, codes, groups, zero, floored,\n           capped, rounded_up).c_str(),\n       bad == 0 && touched == 0 && reached,\n       bad ? fmt("%d differ; first %s", bad, first.c_str())\n           : fmt("%d bytes of other rows touched; a rule of the layout was not reached", touched));\n    /* Negative control: the same comparison against a quantiser that rounds the scale to nearest\n     * must find a difference, or the scale check would not see the rounding rule. */\n    int rn_diff = 0;\n    for (int64_t t = 0; t < T_tok; ++t) {\n        const int32_t s = slots[(size_t)t];\n        if (s < 0 || s / block_size >= n_blocks) continue;\n        for (int64_t h = 0; h < kv_heads; ++h) {\n            const uint8_t* row = &got[(size_t)(((s / block_size) * kv_heads + h) * block_size\n                                               + s % block_size) * rowb];\n            for (int64_t g = 0; g < ng; ++g) {\n                float amax = 0.0f;\n                for (int64_t x = 0; x < G; ++x)\n                    amax = std::fmax(amax, std::fabs(h_bf16(vbits(t, h, g * G + x))));\n                if (!(amax > 0.0f) || !std::isfinite(amax)) continue;\n                const _Float16 rn = (_Float16)std::fmin(amax / 127.0f, 515.5f);\n                uint16_t got_s;\n                std::memcpy(&got_s, row + 3 * head_dim + g * 2, 2);\n                rn_diff += __builtin_bit_cast(uint16_t, rn) != got_s;\n            }\n        }\n    }\n    ok("kv_store_b16i8 negctl", rn_diff > 0,\n       fmt("a round-to-nearest scale must differ: %d groups do", rn_diff));\n}\n\n/* Which rows take a bf16_i8 cache, read off the table (`--case bf16_i8_rows`): the five the layout\n * has and no other -- its prefill and decode at head_dim 256, gqa 6, pages of 16 (each constraint\n * stated, so another geometry resolves to nothing), the store and the fold. No row with a\n * `prefill_fp8` constraint takes it, so the e4m3 product legs have nothing to resolve to; no\n * streamed row does. Then the launches\' own refusals: a descale other than 1 (the layout has no\n * plane for one), and a cache whose token row is another layout\'s (bf16_fp8\'s 3 * head_dim under\n * the bf16_i8 rows, bf16_i8\'s under bf16_fp8\'s). */\nstatic void bf16_i8_rows_case(const Plugin& pl) {\n    if (!sel("bf16_i8_rows")) return;\n    static const char* const want[] = { "attn_prefill_h256_gqa6_b16i8", "attn_decode_h256_gqa6_b16i8",\n                                        "kv_store_b16i8", "qk_norm_rope_gate_kv_store_b16i8" };\n    auto in_set = [](const char* set, const char* v) {\n        const std::string hay = std::string(" ") + (set ? set : "") + " ";\n        return hay.find(std::string(" ") + v + " ") != std::string::npos;\n    };\n    auto eq = [](const RadKernelInfo* r, const char* key, long long v) {\n        for (int c = 0; c < r->n_constraints; ++c)\n            if (r->constraints[c].op == RAD_C_EQ && !std::strcmp(r->constraints[c].key, key))\n                return r->constraints[c].ival == v;\n        return false;\n    };\n    std::string why;\n    int found = 0;\n    for (int k = 0; k < pl.kernel_count(); ++k) {\n        const RadKernelInfo* r = pl.kernel_at(k);\n        bool takes = false, legs = false;\n        for (int c = 0; c < r->n_constraints; ++c) {\n            const RadConstraint& q = r->constraints[c];\n            if (q.op == RAD_C_IN && !std::strcmp(q.key, "kv_dtype") && in_set(q.sval, "bf16_i8")) takes = true;\n            if (!std::strcmp(q.key, "prefill_fp8")) legs = true;\n        }\n        if (!takes) continue;\n        bool known = false;\n        for (const char* w : want) known = known || !std::strcmp(w, r->name);\n        if (!known) why += std::string("; ") + r->name + " takes bf16_i8";\n        if (legs) why += std::string("; ") + r->name + " is an e4m3 product leg";\n        if (std::strstr(r->name, "streamed")) why += std::string("; ") + r->name + " is a streamed row";\n        if (!std::strcmp(r->op, "attn_paged") &&\n            !(eq(r, "head_dim", 256) && eq(r, "gqa", 6) && eq(r, "block_size", 16) && eq(r, "window", 0)))\n            why += std::string("; ") + r->name + " does not pin head_dim 256, gqa 6, block 16, no window";\n        found += known;\n    }\n    if (found != (int)(sizeof want / sizeof want[0])) why += fmt("; %d of the layout\'s rows present", found);\n    ok("bf16_i8: the layout\'s rows and no other take it", why.empty(), why.empty() ? std::string() : why.substr(2));\n\n    const int64_t hd = 256, nkv = 2, bs = 16, nb = 2, M = 2, lane = nkv * hd;\n    const int64_t row_i8 = RAD_KVQ_B16I8_ROW16 * hd / 16, row_f8 = 3 * hd;\n    auto store = [&](const char* name, int64_t rowb, const char* kvd, const char* skey, double sval,\n                     int expect) {\n        const RadKernelInfo* r = find(pl, name);\n        if (!r) { ok(name, false, "row absent"); return; }\n        std::vector<RadTensor> ts = { T(nullptr, RAD_BF16, { M, lane }), T(nullptr, RAD_BF16, { M, lane }),\n                                      TI32({ M }, rep_i32(M, -1)),\n                                      T(nullptr, RAD_F8E4M3, { nb, nkv, bs, rowb }) };\n        std::vector<RadParam> ps = { PI("M", M), PI("head_dim", hd), PI("n_head_kv", nkv),\n                                     PI("block_size", bs), PS("kv_dtype", kvd) };\n        if (skey) ps.push_back(PF(skey, sval));\n        std::printf("  (%s, a %lld-byte row%s%s: expecting rc %d)\\n", name, (long long)rowb,\n                    skey ? ", " : "", skey ? skey : "", expect);\n        run_case(r, ts, ps, expect);\n    };\n    store("kv_store_b16i8", row_i8, "bf16_i8", nullptr, 0, RAD_OK);       /* pad slots: stores nothing */\n    store("kv_store_b16i8", row_i8, "bf16_i8", "k_scale", 2.0, RAD_E_INVAL);\n    store("kv_store_b16i8", row_i8, "bf16_i8", "v_scale", 0.5, RAD_E_INVAL);\n    store("kv_store_b16i8", row_f8, "bf16_i8", nullptr, 0, RAD_E_SHAPE);\n    store("kv_store_b16f8", row_i8, "bf16_fp8", nullptr, 0, RAD_E_SHAPE);\n\n    auto attn = [&](const char* name, int64_t rowb, const char* kvd, int expect) {\n        const RadKernelInfo* r = find(pl, name);\n        if (!r) { ok(name, false, "row absent"); return; }\n        const int64_t gqa = 6, q_len = 1, ctx = 32, mb = ctx / bs;\n        std::vector<RadTensor> ts = {\n            T(nullptr, RAD_BF16, { q_len, nkv * gqa, hd }),\n            T(nullptr, RAD_F8E4M3, { mb, nkv, bs, rowb }),\n            TI32({ 1, mb }, iota_i32(mb)), TI32({ 1 }, rep_i32(1, (int32_t)ctx)),\n            TF32({ 1, nkv }, 1.0f), TF32({ 1, nkv }, 1.0f),\n            T(nullptr, RAD_I32, { 2 }),\n            T(nullptr, RAD_BF16, { q_len, nkv * gqa, hd }),\n        };\n        absent(ts[6]);\n        std::vector<RadParam> ps = {\n            PI("q_len", q_len), PI("head_dim", hd), PI("gqa", gqa), PI("block_size", bs),\n            PI("causal", 1), PI("window", 0), PS("q_dtype", "bf16"), PS("kv_dtype", kvd),\n        };\n        /* run_case takes a refusing scratch hook for a failure; here the hook may be what refuses */\n        for (auto& t : ts) if (!t.data && t.rank) t.data = alloc_for(t);\n        RadArgs ra;\n        std::memset(&ra, 0, sizeof(ra));\n        ra.t = ts.data(); ra.n_t = (int)ts.size(); ra.p = ps.data(); ra.n_p = (int)ps.size();\n        ra.world_size = 1;\n        int64_t need = r->scratch ? r->scratch(&ra) : 0;\n        int rc = need < 0 ? (int)need : RAD_OK;\n        if (need > 0) { ra.scratch = dalloc((size_t)need); ra.scratch_bytes = need; }\n        if (rc == RAD_OK) rc = r->launch(&ra, nullptr);\n        const hipError_t he = (hipError_t)st_stream_sync(nullptr);\n        ok(fmt("%s refuses a %lld-byte token row", name, (long long)rowb).c_str(),\n           rc == expect && he == hipSuccess, fmt("rc=%d, want %d", rc, expect));\n    };\n    /* RAD_E_STRIDE: the reader meets the page\'s token pitch before its extent (fill_paged_row) */\n    attn("attn_prefill_h256_gqa6_b16i8", row_f8, "bf16_i8", RAD_E_STRIDE);\n    attn("attn_decode_h256_gqa6_b16i8",  row_f8, "bf16_i8", RAD_E_STRIDE);\n    attn("attn_prefill_h256_gqa6_b16f8", row_i8, "bf16_fp8", RAD_E_STRIDE);\n    attn("attn_decode_h256_gqa6_b16f8",  row_i8, "bf16_fp8", RAD_E_STRIDE);\n    dfree_all();\n}\n\nstatic void kv_store_case(const Plugin& pl, const char* name, const char* kv_dtype,\n                          bool latent = false) {\n    if (!sel(name)) return;\n', "/* The bf16_i8 quantiser from the layout's definition (RAD_KVQ_B16I8, abi/rad_builder.h), in host"),
