        _edit('arch_test_cpp-1', '    CHECK(noted(b, "kv cache bf16_fp8"));\n}\n\n/* A packed KV cache declares no streamed store and no fold. libr4d\'s streamed rows are the E4M3 and\n * bf16 ones only (libr4d/r4d_rows.cpp), and both streamed ops are weightless, so a declaration with\n * no row for the layout is a device band that resolved to nothing -- a hole, which refuses startup\n', '    CHECK(noted(b, "kv cache bf16_fp8"));\n}\n\n/* --kv-cache-dtype bf16_i8: bf16 K (512 bytes), int8 V (256) and an f16 scale per 32 dims (16), 784\n * bytes a token and head, declared as 49 * 256 / 32 = 392 E4M3 columns; the trunk\'s ops band on\n * kv_dtype bf16_i8 and none on another packed layout\'s, and the drafter\'s group stays E4M3. */\nTEST(qwen35_fp8_bf16_i8_cache_is_784_bytes_a_token_and_head) {\n    CHECK_EQ(RAD_KVQ_B16I8_GROUP, 32);\n    CHECK_EQ(RAD_KVQ_B16I8_ROW16, 49);\n    MetaKV mk = with_dflash2(q35fp8_meta());\n    RadBuilder b;\n    RadBuildCtx ctx = spec_ctx(0, 1, 7);\n    ctx.kv_dtype = RAD_F8E4M3;\n    ctx.kv_quant = RAD_KVQ_B16I8;\n    REQUIRE_EQ(qwen35_fp8::declare(&b, mk.meta(), &ctx), RAD_OK);\n    const RadKVGroupDecl& f = b.kv_groups[0].d;\n    CHECK_EQ(f.dtype, (uint32_t)RAD_F8E4M3);\n    CHECK_EQ(f.head_dim, 392);           /* 2 * 392 = 784 bytes a token and head */\n    CHECK_EQ(b.kv_groups.back().d.head_dim, 128);\n    int i8 = 0, other = 0, e4 = 0;\n    for (const auto& o : b.ops) {\n        const std::string kd = pstr(&o, "kv_dtype");\n        i8 += kd == "bf16_i8"; e4 += kd == "fp8_e4m3";\n        other += kd == "fp8_v4" || kd == "k6_v4" || kd == "bf16_fp8";\n    }\n    CHECK(i8 > 0);\n    CHECK(e4 > 0);                       /* the drafter\'s attention */\n    CHECK_EQ(other, 0);\n    CHECK(noted(b, "kv cache bf16_i8"));\n}\n\n/* A packed KV cache declares no streamed store and no fold. libr4d\'s streamed rows are the E4M3 and\n * bf16 ones only (libr4d/r4d_rows.cpp), and both streamed ops are weightless, so a declaration with\n * no row for the layout is a device band that resolved to nothing -- a hole, which refuses startup\n', '/* --kv-cache-dtype bf16_i8: bf16 K (512 bytes), int8 V (256) and an f16 scale per 32 dims (16), 784'),
        _edit('arch_test_cpp-2', '            CHECK_EQ(count_op(b, "kv_store_streamed"), 0);\n            CHECK_EQ(count_op(b, "qk_norm_rope_gate_kv_store_streamed"), 0);\n        }\n    }\n}\n\n/* --attn-prefill-fp8: the trunk\'s attn_paged ops state `prefill_fp8` with the context\'s bits and\n', '            CHECK_EQ(count_op(b, "kv_store_streamed"), 0);\n            CHECK_EQ(count_op(b, "qk_norm_rope_gate_kv_store_streamed"), 0);\n        }\n        /* bf16_fp8 and bf16_i8 are qwen35\'s alone: the same gate there, at 48 and 49 * head_dim / 32\n         * columns, and a plugin that does not know the layout refuses it rather than declare E4M3. */\n        for (int q : { (int)RAD_KVQ_B16F8, (int)RAD_KVQ_B16I8 }) {\n            RadBuildCtx ctx = plain;\n            ctx.kv_quant = q;\n            RadBuilder b;\n            if (pl.declare != qwen35_fp8::declare) {\n                CHECK_EQ(stderr_of_rc([&] { return pl.declare(&b, pl.meta, &ctx); }), RAD_E_UNSUPPORTED);\n                continue;\n            }\n            REQUIRE_EQ(pl.declare(&b, pl.meta, &ctx), RAD_OK);\n            const RadKVGroupDecl& f = b.kv_groups[0].d;\n            CHECK_EQ(f.dtype, (uint32_t)RAD_F8E4M3);\n            CHECK_EQ(f.head_dim, q == RAD_KVQ_B16F8 ? (int64_t)384 : (int64_t)392);\n            CHECK(count_op(b, "kv_store") > 0);\n            CHECK_EQ(count_op(b, "kv_resolve"), count_op(p, "kv_resolve"));\n            CHECK_EQ(count_op(b, "kv_store_streamed"), 0);\n            CHECK_EQ(count_op(b, "qk_norm_rope_gate_kv_store_streamed"), 0);\n        }\n    }\n    /* and its probe does not offer them */\n    RadArchProbe p4{};\n    CHECK_OK(qwen4exp_fp8::probe(&m4, &p4));\n    CHECK_EQ(p4.kv_quant_ok & ((1 << RAD_KVQ_B16F8) | (1 << RAD_KVQ_B16I8)), 0);\n}\n\n/* --attn-prefill-fp8: the trunk\'s attn_paged ops state `prefill_fp8` with the context\'s bits and\n', "/* bf16_fp8 and bf16_i8 are qwen35's alone: the same gate there, at 48 and 49 * head_dim / 32"),
        _edit('arch_test_cpp-3', '\n    /* Over the fp8_v4 and k6_v4 layouts the trunk\'s attention states it beside the layout\'s\n     * kv_dtype, which is what libr4d\'s legs for those caches match. */\n    for (int kvq : { (int)RAD_KVQ_V4, (int)RAD_KVQ_K6V4, (int)RAD_KVQ_B16F8 }) {\n        RadBuilder q;\n        RadBuildCtx cq = spec_ctx(0, 1, 7);\n        cq.kv_dtype = RAD_F8E4M3;\n        cq.kv_quant = kvq;\n        cq.attn_prefill_fp8 = RAD_ATTN_FP8_PV;\n        REQUIRE_EQ(qwen35_fp8::declare(&q, mk.meta(), &cq), RAD_OK);\n        const std::string want = kvq == RAD_KVQ_V4 ? "fp8_v4" : kvq == RAD_KVQ_K6V4 ? "k6_v4" : "bf16_fp8";\n        int legs = 0;\n        for (const auto& o : q.ops) {\n            const RecParam* p = param(&o, "prefill_fp8");\n', '\n    /* Over the fp8_v4 and k6_v4 layouts the trunk\'s attention states it beside the layout\'s\n     * kv_dtype, which is what libr4d\'s legs for those caches match. */\n    for (int kvq : { (int)RAD_KVQ_V4, (int)RAD_KVQ_K6V4, (int)RAD_KVQ_B16F8, (int)RAD_KVQ_B16I8 }) {\n        RadBuilder q;\n        RadBuildCtx cq = spec_ctx(0, 1, 7);\n        cq.kv_dtype = RAD_F8E4M3;\n        cq.kv_quant = kvq;\n        cq.attn_prefill_fp8 = RAD_ATTN_FP8_PV;\n        REQUIRE_EQ(qwen35_fp8::declare(&q, mk.meta(), &cq), RAD_OK);\n        const std::string want = kvq == RAD_KVQ_V4 ? "fp8_v4" : kvq == RAD_KVQ_K6V4 ? "k6_v4"\n                               : kvq == RAD_KVQ_B16F8 ? "bf16_fp8" : "bf16_i8";\n        int legs = 0;\n        for (const auto& o : q.ops) {\n            const RecParam* p = param(&o, "prefill_fp8");\n', 'for (int kvq : { (int)RAD_KVQ_V4, (int)RAD_KVQ_K6V4, (int)RAD_KVQ_B16F8, (int)RAD_KVQ_B16I8 }) {'),
