        _edit('config_test_cpp-1', '    CHECK_EQ(parse({ "--kv-cache-dtype", "bf16_fp8" }, &c), RAD_OK);\n    CHECK_EQ(c.kv_cache_dtype, std::string("bf16_fp8"));\n    CHECK_EQ(bc_kv_quant_of("bf16_fp8"), (int)RAD_KVQ_B16F8);\n    CHECK_EQ(bc_kv_quant_of("fp8"), (int)RAD_KVQ_NONE);\n    /* Five values only: an "auto" resolving to bf16 would be a second name for the default, and\n     * each value should be unambiguous in a log. */\n    CHECK_EQ(parse({ "--kv-cache-dtype", "auto" }, &c), RAD_E_INVAL);\n    CHECK_EQ(parse({ "--kv-cache-dtype", "fp16" }, &c), RAD_E_INVAL);\n', '    CHECK_EQ(parse({ "--kv-cache-dtype", "bf16_fp8" }, &c), RAD_OK);\n    CHECK_EQ(c.kv_cache_dtype, std::string("bf16_fp8"));\n    CHECK_EQ(bc_kv_quant_of("bf16_fp8"), (int)RAD_KVQ_B16F8);\n    CHECK_EQ(parse({ "--kv-cache-dtype", "bf16_i8" }, &c), RAD_OK);\n    CHECK_EQ(c.kv_cache_dtype, std::string("bf16_i8"));\n    CHECK_EQ(bc_kv_quant_of("bf16_i8"), (int)RAD_KVQ_B16I8);\n    CHECK_EQ(bc_kv_quant_of("fp8_v4"), (int)RAD_KVQ_V4);\n    CHECK_EQ(bc_kv_quant_of("k6_v4"), (int)RAD_KVQ_K6V4);\n    CHECK_EQ(bc_kv_quant_of("fp8"), (int)RAD_KVQ_NONE);\n    CHECK_EQ(bc_kv_quant_of("bf16"), (int)RAD_KVQ_NONE);\n    CHECK_EQ(parse({ "--kv-cache-dtype", "bf16_i4" }, &c), RAD_E_INVAL);\n    CHECK_EQ(parse({ "--kv-cache-dtype", "i8" }, &c), RAD_E_INVAL);\n    /* Six values only: an "auto" resolving to bf16 would be a second name for the default, and\n     * each value should be unambiguous in a log. */\n    CHECK_EQ(parse({ "--kv-cache-dtype", "auto" }, &c), RAD_E_INVAL);\n    CHECK_EQ(parse({ "--kv-cache-dtype", "fp16" }, &c), RAD_E_INVAL);\n', 'CHECK_EQ(parse({ "--kv-cache-dtype", "bf16_i8" }, &c), RAD_OK);'),
